parameters.functionScript:
// OLIVE_ON (scripts/olive.js) off: a request whose goal or reference program uses an Olive block is left out.
var list = Scripts.olive.oliveRequests(Array.isArray(Inputs.requests) ? Inputs.requests : []);
Outputs.requests = list;
Outputs.count = list.length;

